package cn.mop.persistence;
import com.zaxxer.hikari.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import java.sql.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
/** Real PG constraints. Isolated uncommitted tenant rows use migrator; two explicit ACL/trigger checks use runtime. */
@EnabledIfEnvironmentVariable(named="MOP_RUN_REMOTE_TESTS",matches="true")
class PostgresCustomerContactSchemaIntegrationTest {
    static HikariDataSource migrator,runtime;Connection connection;String tenant,actor;
    static HikariDataSource pool(String username,String password){String url=System.getenv("SPRING_DATASOURCE_URL");assertNotNull(url);assertTrue(url.matches("jdbc:postgresql://127\\.0\\.0\\.1:[0-9]+/mop_test"));var cfg=new HikariConfig();cfg.setJdbcUrl(url);cfg.setUsername(username);cfg.setPassword(password);cfg.setMaximumPoolSize(2);cfg.setConnectionTimeout(5000);return new HikariDataSource(cfg);}
    @BeforeAll static void connect(){assertEquals("mop_test_migrator",System.getenv("MOP_MIGRATION_USERNAME"));assertEquals("mop_test_runtime",System.getenv("SPRING_DATASOURCE_USERNAME"));migrator=pool(System.getenv("MOP_MIGRATION_USERNAME"),System.getenv("MOP_MIGRATION_PASSWORD"));runtime=pool(System.getenv("SPRING_DATASOURCE_USERNAME"),System.getenv("SPRING_DATASOURCE_PASSWORD"));}
    @BeforeEach void begin()throws SQLException{connection=migrator.getConnection();connection.setAutoCommit(false);tenant=UUID.randomUUID().toString();actor=scalar("SELECT user_id::text FROM public.mop_membership WHERE tenant_id='55000000-0000-4000-8000-000000000001'::uuid AND role_code='padmin' AND active LIMIT 1");sql("INSERT INTO public.mop_tenant(id,name) VALUES ('"+tenant+"','SYNTHETIC_CONTACT_SCHEMA_"+tenant+"')");sql("INSERT INTO public.mop_membership(tenant_id,user_id,role_code,active) VALUES ('"+tenant+"','"+actor+"','padmin',false)");}
    @AfterEach void rollback()throws SQLException{if(connection!=null){connection.rollback();connection.close();}}
    @AfterAll static void close(){if(migrator!=null)migrator.close();if(runtime!=null)runtime.close();}
    void sql(String sql)throws SQLException{try(var s=connection.createStatement()){s.execute(sql);}}
    String scalar(String sql)throws SQLException{try(var s=connection.createStatement();var r=s.executeQuery(sql)){assertTrue(r.next());return r.getString(1);}}
    @FunctionalInterface interface Action{void run()throws SQLException;}
    void rejected(String state,Action action)throws SQLException{Savepoint p=connection.setSavepoint();SQLException e=assertThrows(SQLException.class,action::run);assertEquals(state,e.getSQLState());connection.rollback(p);connection.releaseSavepoint(p);}
    String insert(String roles,boolean enabled,String fields,String values)throws SQLException{String id=UUID.randomUUID().toString();sql("INSERT INTO public.mop_customer_contact(id,tenant_id,created_by) VALUES ('"+id+"','"+tenant+"','"+actor+"')");sql("INSERT INTO public.mop_customer_contact_revision(tenant_id,contact_id,version,recorded_by,action,name,roles,enabled"+fields+") VALUES ('"+tenant+"','"+id+"',1,'"+actor+"','CREATE','合成联系人',"+roles+","+enabled+values+")");return id;}
    String decision()throws SQLException{return insert("ARRAY['DECISION_MAKER']",true,"","");}
    void version(String id,int version,String action,boolean enabled,boolean archived,String roles)throws SQLException{sql("INSERT INTO public.mop_customer_contact_revision(tenant_id,contact_id,version,previous_version,recorded_by,action,name,roles,enabled,archived) VALUES ('"+tenant+"','"+id+"',"+version+","+(version-1)+",'"+actor+"','"+action+"','合成修订',"+roles+","+enabled+","+archived+")");sql("UPDATE public.mop_customer_contact SET version="+version+",updated_at=statement_timestamp() WHERE id='"+id+"'");}
    void validate()throws SQLException{sql("SET CONSTRAINTS ALL IMMEDIATE");sql("SET CONSTRAINTS ALL DEFERRED");}
    @Test void firstDecisionPreservesUnknownContactAndPreferenceFields()throws SQLException{String id=decision();validate();assertEquals("SELF_REPORTED_CONTACT",scalar("SELECT record_source FROM public.mop_customer_contact_revision WHERE contact_id='"+id+"'"));for(String key:List.of("mobile","email","wecom_user_id","preferred_priorities","quiet_enabled","quiet_start","quiet_end"))assertEquals("true",scalar("SELECT ("+key+" IS NULL)::text FROM public.mop_customer_contact_revision WHERE contact_id='"+id+"'"));assertEquals("1",scalar("SELECT version FROM public.mop_contact_tenant_guard WHERE tenant_id='"+tenant+"'"));}
    @Test void explicitEmptyPrioritiesAndThreeQuietPreferenceStatesRoundTrip()throws SQLException{decision();String id=insert("ARRAY['REPORTER']",true,",preferred_priorities,quiet_declared,quiet_enabled,quiet_start,quiet_end",",ARRAY[]::text[],true,true,'22:30','07:15'");validate();assertEquals("0",scalar("SELECT cardinality(preferred_priorities) FROM public.mop_customer_contact_revision WHERE contact_id='"+id+"'"));insert("ARRAY['TECHNICAL_CONTACT']",false,",quiet_declared,quiet_enabled",",true,false");insert("ARRAY['REPORTER']",true,",quiet_declared",",true");validate();}
    @Test void unknownDuplicateNullAndEmptyRoleArraysRejected()throws SQLException{for(String roles:List.of("ARRAY[]::text[]","ARRAY['OTHER']","ARRAY['REPORTER','REPORTER']","ARRAY['REPORTER',NULL]","'[0:0]={REPORTER}'::text[]"))rejected("23514",()->insert(roles,true,"",""));}
    @Test void invalidChannelSyntaxAndPrioritySetsRejected()throws SQLException{for(String email:List.of("a..b@example.test","a@localhost","a@@example.test","a@-example.test"))rejected("23514",()->insert("ARRAY['DECISION_MAKER']",true,",email",",'"+email+"'"));for(String mobile:List.of("13800000000","+0123","+1 234"))rejected("23514",()->insert("ARRAY['DECISION_MAKER']",true,",mobile",",'"+mobile+"'"));for(String prefs:List.of("ARRAY['P5']","ARRAY['P1','P1']","ARRAY['P1',NULL]"))rejected("23514",()->insert("ARRAY['DECISION_MAKER']",true,",preferred_priorities",","+prefs));}
    @Test void quietAmbiguityAndUndeclaredValuesRejected()throws SQLException{for(String values:List.of("true,true,'12:00','12:00'","true,true,NULL,'12:00'","true,false,'12:00',NULL","false,true,'22:00','07:00'","true,true,'24:00','07:00'"))rejected("23514",()->insert("ARRAY['DECISION_MAKER']",true,",quiet_declared,quiet_enabled,quiet_start,quiet_end",","+values));}
    @Test void crossTenantActorAndOrphanCurrentRevisionRejected()throws SQLException{String foreign=scalar("SELECT user_id::text FROM public.mop_membership WHERE user_id<>'"+actor+"'::uuid LIMIT 1");rejected("23503",()->sql("INSERT INTO public.mop_customer_contact(id,tenant_id,created_by) VALUES (gen_random_uuid(),'"+tenant+"','"+foreign+"')"));rejected("23503",()->{sql("INSERT INTO public.mop_customer_contact(id,tenant_id,created_by) VALUES (gen_random_uuid(),'"+tenant+"','"+actor+"')");sql("SET CONSTRAINTS mop_contact_current_revision IMMEDIATE");});}
    @Test void missingPreviousRevisionAndInvalidArchiveCombinationsRejected()throws SQLException{String id=decision();validate();rejected("23503",()->version(id,3,"UPDATE",true,false,"ARRAY['DECISION_MAKER']"));rejected("23514",()->version(id,2,"ARCHIVE",true,true,"ARRAY['DECISION_MAKER']"));rejected("23514",()->version(id,2,"UPDATE",false,true,"ARRAY['DECISION_MAKER']"));}
    @Test void firstNonDecisionOrDisabledDecisionCannotPassDeferredGuard()throws SQLException{for(String roles:List.of("ARRAY['REPORTER']","ARRAY['DECISION_MAKER']"))rejected("23514",()->{insert(roles,!roles.contains("DECISION"),"","");validate();});assertEquals("0",scalar("SELECT count(*) FROM public.mop_customer_contact WHERE tenant_id='"+tenant+"'"));}
    @Test void lastEnabledDecisionCannotBeDisabledLoseRoleOrArchived()throws SQLException{String id=decision();validate();rejected("23514",()->{version(id,2,"UPDATE",false,false,"ARRAY['DECISION_MAKER']");validate();});rejected("23514",()->{version(id,2,"UPDATE",true,false,"ARRAY['REPORTER']");validate();});rejected("23514",()->{version(id,2,"ARCHIVE",false,true,"ARRAY['DECISION_MAKER']");validate();});assertEquals("1",scalar("SELECT version FROM public.mop_customer_contact WHERE id='"+id+"'"));}
    @Test void anotherEnabledDecisionPermitsArchiveAndExplicitRestoreWithHistory()throws SQLException{String first=decision();decision();validate();version(first,2,"ARCHIVE",false,true,"ARRAY['DECISION_MAKER']");validate();version(first,3,"RESTORE",true,false,"ARRAY['DECISION_MAKER']");validate();assertEquals("3",scalar("SELECT count(*) FROM public.mop_customer_contact_revision WHERE contact_id='"+first+"'"));}
    void asRuntime()throws SQLException{connection.rollback();connection.close();connection=runtime.getConnection();connection.setAutoCommit(false);tenant="55000000-0000-4000-8000-000000000001";}
    @Test void actualRuntimeCanExecuteDeferredGuardWithoutElevatedFunctionOrPublicGrant()throws SQLException{asRuntime();assertEquals("mop_test_runtime",scalar("SELECT current_user"));String id=decision();validate();assertEquals("1",scalar("SELECT count(*) FROM public.mop_customer_contact WHERE id='"+id+"'"));assertEquals("false",scalar("SELECT prosecdef::text FROM pg_proc WHERE oid='public.mop_contact_decision_guard()'::regprocedure"));assertEquals("0",scalar("SELECT count(*) FROM pg_proc p CROSS JOIN LATERAL aclexplode(p.proacl) a WHERE p.oid='public.mop_contact_decision_guard()'::regprocedure AND a.grantee=0"));}
    @Test void actualRuntimeCannotRewriteHistoryScopeOrDelete()throws SQLException{asRuntime();for(String sql:List.of("UPDATE public.mop_customer_contact_revision SET name='changed' WHERE false","UPDATE public.mop_customer_contact SET tenant_id=gen_random_uuid() WHERE false","UPDATE public.mop_customer_contact SET created_by=gen_random_uuid() WHERE false","DELETE FROM public.mop_customer_contact WHERE false","DELETE FROM public.mop_customer_contact_revision WHERE false","TRUNCATE public.mop_contact_tenant_guard"))rejected("42501",()->sql(sql));for(String table:List.of("mop_contact_tenant_guard","mop_customer_contact","mop_customer_contact_revision"))assertEquals("0",scalar("SELECT count(*) FROM pg_class c CROSS JOIN LATERAL aclexplode(c.relacl) a WHERE c.oid='public."+table+"'::regclass AND a.grantee=0"));}
}
